const DIAS = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const DIASAC = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const ahora = new Date();
const hoyISO = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Madrid', year:'numeric', month:'2-digit', day:'2-digit' }).format(ahora);
const horaMadrid = new Intl.DateTimeFormat('es-ES', { timeZone: 'Europe/Madrid', hour:'2-digit', minute:'2-digit', hour12:false }).format(ahora);
const p = hoyISO.split('-').map(Number);
const Y = p[0], M = p[1], D = p[2];
const dowHoy = new Date(Date.UTC(Y, M-1, D, 12)).getUTCDay();
let lineas = [];
for (let i = 0; i < 14; i++) {
  const d = new Date(Date.UTC(Y, M-1, D + i, 12));
  const dd = String(d.getUTCDate()).padStart(2,'0');
  const mm = String(d.getUTCMonth()+1).padStart(2,'0');
  const etq = i === 0 ? ' (hoy)' : (i === 1 ? ' (mañana)' : '');
  lineas.push('- ' + DIASAC[d.getUTCDay()] + ' ' + dd + '/' + mm + '/' + d.getUTCFullYear() + etq);
}
const texto =
  'Hoy es ' + DIASAC[dowHoy] + ' ' + D + ' de ' + MESES[M-1] + ' de ' + Y + '. ' +
  'La hora actual en España (Europe/Madrid) es ' + horaMadrid + '.\n\n' +
  'IMPORTANTE: el año actual es ' + Y + '. Usa SIEMPRE este año y estas fechas exactas. NUNCA asumas otro año ni calcules el día de la semana por tu cuenta: usa esta tabla de los proximos dias para interpretar "hoy", "mañana", "el sabado que viene", etc.\n' +
  lineas.join('\n') + '\n\n' +
  'Considera este valor como el "ahora" de la conversacion y usalo para interpretar expresiones temporales.';
return [{ json: { texto } }];
